css:
.loader {
  position: relative;
  width: 46px;
  height: 46px;
  border-radius: 4px;
  overflow: hidden;
  background-color: #eef2ff;
  background-image:
    linear-gradient(#6366f1 0 0),
    linear-gradient(#6366f1 0 0),
    linear-gradient(#6366f1 0 0),
    conic-gradient(from 0deg, #6366f1 25%, transparent 0 50%, #6366f1 0 75%, transparent 0);
  background-repeat: no-repeat, no-repeat, no-repeat, repeat;
  background-size: 12px 12px, 12px 12px, 12px 12px, 10px 10px;
  background-position: 0 0, 100% 0, 0 100%, 0 0;
}
.loader i {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 4px;
  background: #6366f1;
  box-shadow: 0 0 6px 1px #6366f1;
  animation: qscan 1.6s ease-in-out infinite;
}
@keyframes qscan {
  0% { top: 0; }
  50% { top: calc(100% - 4px); }
  100% { top: 0; }
}
